// authRouteConfig.js
import Login from "views/examples/Login.js";
import Register from "views/examples/Register.js";

const authRouteConfig = [
  {
    path: "/login",
    name: "Login",
    component: <Login />,
    layout: "/auth",
  },
  {
    path: "/register",
    name: "Register",
    component: <Register />,
    layout: "/auth",
  },
];

export default authRouteConfig;
